class Solution {
  public java.util.List<Boolean> areConnected(int n, int threshold, int[][] queries) {
    DSU dsu = new DSU(n + 1);
    for (int divisor = threshold + 1; divisor <= n; divisor++)
      for (int multiple = divisor * 2; multiple <= n; multiple += divisor)
        dsu.union(divisor, multiple);
    java.util.List<Boolean> result = new java.util.ArrayList<>();
    for (int[] q : queries) result.add(dsu.find(q[0]) == dsu.find(q[1]));
    return result;
  }

  private static class DSU {
    int[] parent;

    DSU(int n) {
      parent = new int[n];
      for (int i = 0; i < n; i++) parent[i] = i;
    }

    int find(int x) {
      return parent[x] == x ? x : (parent[x] = find(parent[x]));
    }

    void union(int a, int b) {
      a = find(a);
      b = find(b);
      if (a != b) parent[a] = b;
    }
  }
}
